import React from 'react';
import { useLocation } from 'react-router-dom';

function Detalhes() {
  const location = useLocation();
  const queryParams = new URLSearchParams(location.search);

  const nomeCompleto = queryParams.get('nomeCompleto');
  const dataNascimento = queryParams.get('dataNascimento');
  const telefone = queryParams.get('telefone');

  return (
    <div className="App min-h-screen bg-gray-100 flex items-center justify-center">
      <div className="w-full max-w-md p-6 bg-white rounded-lg shadow-md">
        <h1 className="text-2xl font-bold mb-6 text-gray-800">Detalhes do Cadastro</h1>
        <p><strong>Nome Completo:</strong> {nomeCompleto}</p>
        <p><strong>Data de Nascimento:</strong> {dataNascimento}</p>
        <p><strong>Telefone:</strong> {telefone}</p>
      </div>
    </div>
  );
}

export default Detalhes;
